const fs = require('fs');
const readline = require('readline');
const path = require('path');

const transcriptPath = 'C:/Users/admin/.gemini/antigravity-ide/brain/53b57104-e4e2-40d0-adc5-813cc565893f/.system_generated/logs/transcript_full.jsonl';

async function recover() {
  const fileStream = fs.createReadStream(transcriptPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const parts = [];

  for await (const line of rl) {
    if (!line.trim()) continue;
    const step = JSON.parse(line);

    if (step.source === 'SYSTEM' && step.content) {
      const content = String(step.content);
      if (/purchase\.js/i.test(content) && /Showing lines \d+ to \d+/i.test(content)) {
        // Find which lines were shown
        const match = content.match(/Showing lines (\d+) to (\d+)/i);
        if (match) {
          const start = parseInt(match[1]);
          const end = parseInt(match[2]);
          console.log(`Found snippet from step ${step.step_index}: showing lines ${start} to ${end}`);
          parts.push({
            step: step.step_index,
            start,
            end,
            content
          });
        }
      }
    }
  }

  // Sort parts by start line
  parts.sort((a, b) => a.start - b.start);

  // Let's print out what ranges we have
  parts.forEach(p => {
    console.log(`Range: ${p.start} - ${p.end} (from step ${p.step})`);

    // Write each snippet to a file in scratch
    const outPath = path.join('C:/Users/admin/.gemini/antigravity-ide/brain/53b57104-e4e2-40d0-adc5-813cc565893f/scratch', `purchase_js_step_${p.step}_lines_${p.start}_${p.end}.txt`);
    fs.writeFileSync(outPath, p.content);
    console.log(`  Saved snippet to: ${outPath}`);
  });
}

recover().catch(err => console.error(err));
